    var value: Int

    enum CodingKeys: String, CodingKey {
        case next = "next"
        case value = "value"
    }

    init(next: Node?, value: Int) {
        self.next = next
        self.value = value
    }
}

// MARK: Node convenience initializers and mutators

extension Node {
    convenience init(data: Data) throws {
        let me = try newJSONDecoder().decode(Node.self, from: data)
        self.init(next: me.next, value: me.value)
    }

    convenience init(_ json: String, using encoding: String.Encoding = .utf8) throws {
        guard let data = json.data(using: encoding) else {
            throw NSError(domain: "JSONDecoding", code: 0, userInfo: nil)
        }
        try self.init(data: data)
    }

    convenience init(fromURL url: URL) throws {
        try self.init(data: try Data(contentsOf: url))
    }

    func with(
        next: Node?? = nil,
        value: Int? = nil
    ) -> Node {
        return Node(
            next: next ?? self.next,
            value: value ?? self.value
        )
    }

    func jsonData() throws -> Data {
        return try newJSONEncoder().encode(self)
    }

    func jsonString(encoding: String.Encoding = .utf8) throws -> String? {
        return String(data: try self.jsonData(), encoding: encoding)
    }
}

enum Numbers: Codable {
    case bool(Bool)
    case double(Double)
    case integer(Int)
    case null

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let x = try? container.decode(Bool.self) {
            self = .bool(x)
            return
        }
        if let x = try? container.decode(Int.self) {
            self = .integer(x)
            return
        }
        if let x = try? container.decode(Double.self) {
            self = .double(x)
            return
        }
        if container.decodeNil() {
            self = .null
            return
        }
        throw DecodingError.typeMismatch(Numbers.self, DecodingError.Context(codingPath: decoder.codingPath, debugDescription: "Wrong type for Numbers"))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .bool(let x):
            try container.encode(x)
        case .double(let x):
            try container.encode(x)
        case .integer(let x):
            try container.encode(x)
        case .null:
            try container.encodeNil()
        }
    }
}

